package it.penny.api.support;

import it.penny.api.security.*;
import it.penny.api.common.AuditLog;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.http.HttpStatus;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.server.ResponseStatusException;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.security.core.Authentication;
import java.time.*;
import java.util.*;

@RestController @RequestMapping("/api/support-calls")
public class SupportController {
 final JdbcTemplate db;final PennyUserRepository users;final RbacService rbac;final AuditLog audit;
 public SupportController(JdbcTemplate db,PennyUserRepository users,RbacService rbac,AuditLog audit){this.db=db;this.users=users;this.rbac=rbac;this.audit=audit;}
 PennyUser require(Authentication a,boolean write){var u=a==null?null:users.findByEmailIgnoreCase(a.getName()).orElse(null);rbac.require(u,"CUSTOMERS_READ");rbac.require(u,"ACTIVITIES_READ");if(write)rbac.require(u,"ACTIVITIES_WRITE");return u;}
 static ResponseStatusException bad(String message){return new ResponseStatusException(HttpStatus.BAD_REQUEST,message);}
 void customer(long id){if(!Boolean.TRUE.equals(db.queryForObject("SELECT EXISTS(SELECT 1 FROM penny_customers WHERE id=? AND deleted_at IS NULL)",Boolean.class,id)))throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Cliente non disponibile");}
 static final String FROM=" FROM penny_support_calls s JOIN penny_customer_records r ON r.id=s.record_id JOIN penny_customers c ON c.id=r.customer_id JOIN penny_users u ON u.id=s.technician_id WHERE r.deleted_at IS NULL AND c.deleted_at IS NULL";
 static final String FIELDS="SELECT s.record_id AS id,r.customer_id AS \"customerId\",c.name AS \"customerName\",s.contact_id AS \"contactId\",s.requester_name AS \"requesterName\",s.technician_id AS \"technicianId\",u.full_name AS \"technicianName\",r.name,r.notes AS description,r.reference,s.started_at AS \"startedAt\",s.ended_at AS \"endedAt\",s.outcome,CASE WHEN s.ended_at IS NOT NULL THEN extract(epoch FROM (s.ended_at-s.started_at))::bigint END AS \"durationSeconds\"";
 Map<String,Object> row(long id,boolean lock){var rows=db.queryForList(FIELDS+FROM+" AND s.record_id=?"+(lock?" FOR UPDATE OF s":""),id);if(rows.isEmpty())throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Tele-assistenza non disponibile");return rows.getFirst();}
 @GetMapping("/technicians") public Map<String,Object> technicians(Authentication a){require(a,true);return Map.of("items",db.queryForList("SELECT id,full_name AS name FROM penny_users WHERE enabled AND NOT must_change_password ORDER BY full_name,id").stream().filter(u->eligible(((Number)u.get("id")).longValue())).toList());}
 boolean eligible(long id){return rbac.allowed(id,"ACTIVITIES_READ")&&rbac.allowed(id,"ACTIVITIES_WRITE")&&rbac.allowed(id,"CUSTOMERS_READ");}
 public record NewContact(String name,String email,String phone){}
 public record Open(Long customerId,Long contactId,NewContact newContact,Long technicianId,String description){}
 @PostMapping @Transactional public Map<String,Object> open(@RequestBody Open input,Authentication a){var actor=require(a,true);if(input.customerId()==null||input.technicianId()==null)throw bad("Seleziona cliente e tecnico");customer(input.customerId());if(input.description()!=null&&input.description().length()>2000)throw bad("Motivo troppo lungo (massimo 2000 caratteri)");
  var technicians=db.queryForList("SELECT id FROM penny_users WHERE id=? AND enabled AND NOT must_change_password",input.technicianId());if(technicians.isEmpty()||!eligible(input.technicianId()))throw bad("Tecnico non disponibile");
  Long contact=input.contactId();if(input.newContact()!=null){if(contact!=null)throw bad("Scegli un contatto oppure inseriscine uno nuovo");rbac.require(actor,"CUSTOMERS_WRITE");var n=input.newContact();if(n.name()==null||n.name().isBlank()||n.name().length()>200||n.email()!=null&&(n.email().length()>254||!n.email().isBlank()&&!n.email().matches("[^\\s@]+@[^\\s@]+\\.[^\\s@]+"))||n.phone()!=null&&n.phone().length()>40)throw bad("Dati del nuovo contatto non validi");contact=db.queryForObject("INSERT INTO penny_customer_contacts(customer_id,full_name,email,phone) VALUES (?,?,?,?) RETURNING id",Long.class,input.customerId(),n.name().trim(),n.email()==null||n.email().isBlank()?null:n.email().trim(),n.phone());}
  var contacts=contact==null?List.<Map<String,Object>>of():db.queryForList("SELECT p.full_name FROM penny_customer_contacts p JOIN penny_contact_customers l ON l.contact_id=p.id WHERE p.id=? AND l.customer_id=? AND p.deleted_at IS NULL",contact,input.customerId());if(contacts.isEmpty())throw bad("Seleziona un contatto associato al cliente");
  var now=Instant.now();long id=db.queryForObject("INSERT INTO penny_customer_records(customer_id,kind,name,status,starts_on,notes,details) VALUES (?,'INTERVENTION','Tele-assistenza','IN_PROGRESS',?,?,jsonb_build_object('teleAssistance',true,'interventionType','REMOTE_SUPPORT','venue','ONLINE','contactId',?::bigint,'technicianUserId',?::bigint)) RETURNING id",Long.class,input.customerId(),LocalDate.ofInstant(now,ZoneId.of("Europe/Rome")),input.description(),contact,input.technicianId());
  db.update("INSERT INTO penny_support_calls(record_id,contact_id,requester_name,technician_id,created_by,started_at) VALUES (?,?,?,?,?,?)",id,contact,contacts.getFirst().get("full_name"),input.technicianId(),actor.id,java.sql.Timestamp.from(now));audit.record(a,"SUPPORT_CALL_OPENED","CUSTOMER_RECORD",id,Map.of("customerId",input.customerId(),"technicianId",input.technicianId()));return detail(id,a);
 }
 @GetMapping("/{id}") public Map<String,Object> detail(@PathVariable long id,Authentication a){require(a,false);var r=row(id,false);r.put("serverNow",Instant.now());r.put("comments",db.queryForList("SELECT s.id,s.body,s.created_at AS \"createdAt\",u.full_name AS author FROM penny_support_comments s JOIN penny_users u ON u.id=s.author_id WHERE record_id=? ORDER BY s.id",id));return r;}
 public record Close(String outcome,Instant endedAt,String comment){}
 @PostMapping("/{id}/close") @Transactional public Map<String,Object> close(@PathVariable long id,@RequestBody Close input,Authentication a){var u=require(a,true);var r=row(id,true);if(!"IN_PROGRESS".equals(r.get("outcome")))throw new ResponseStatusException(HttpStatus.CONFLICT,"Assistenza già chiusa: ricarica il dettaglio");var start=((java.sql.Timestamp)r.get("startedAt")).toInstant();if(!Set.of("RESOLVED","PARTIAL","UNRESOLVED").contains(Objects.toString(input.outcome(),""))||input.endedAt()==null||input.endedAt().isBefore(start)||input.endedAt().isAfter(Instant.now().plusSeconds(120)))throw bad("Esito o orario di chiusura non valido: la fine deve essere successiva all'apertura e non nel futuro");validateComment(input.comment(),false);
  db.update("UPDATE penny_support_calls SET outcome=?,ended_at=? WHERE record_id=?",input.outcome(),java.sql.Timestamp.from(input.endedAt()),id);db.update("UPDATE penny_customer_records SET status='COMPLETED',expires_on=?,updated_at=now() WHERE id=?",LocalDate.ofInstant(input.endedAt(),ZoneId.of("Europe/Rome")),id);if(input.comment()!=null&&!input.comment().isBlank())db.update("INSERT INTO penny_support_comments(record_id,author_id,body) VALUES (?,?,?)",id,u.id,input.comment().trim());audit.record(a,"SUPPORT_CALL_CLOSED","CUSTOMER_RECORD",id,Map.of("outcome",input.outcome()));return detail(id,a);
 }
 static void validateComment(String value,boolean required){if(required&&(value==null||value.isBlank())||value!=null&&value.length()>5000)throw bad("Commento: da 1 a 5000 caratteri");}
 public record Comment(String body){}
 @PostMapping("/{id}/comments") @Transactional public Map<String,Object> comment(@PathVariable long id,@RequestBody Comment input,Authentication a){var u=require(a,true);row(id,false);validateComment(input.body(),true);long comment=db.queryForObject("INSERT INTO penny_support_comments(record_id,author_id,body) VALUES (?,?,?) RETURNING id",Long.class,id,u.id,input.body().trim());audit.record(a,"SUPPORT_CALL_COMMENTED","CUSTOMER_RECORD",id,Map.of("commentId",comment));return Map.of("id",comment);}
 @DeleteMapping("/{id}") @Transactional public Map<String,Object> cancel(@PathVariable long id,Authentication a){require(a,true);row(id,true);db.update("DELETE FROM penny_record_interventions WHERE record_id=? OR intervention_id=?",id,id);db.update("UPDATE penny_documents SET record_id=NULL WHERE record_id=?",id);db.update("DELETE FROM penny_record_tasks WHERE record_id=?",id);db.update("DELETE FROM penny_customer_records WHERE id=?",id);audit.record(a,"SUPPORT_CALL_CANCELLED","CUSTOMER_RECORD",id,Map.of());return Map.of("cancelled",true);}
 @GetMapping public Map<String,Object> list(@RequestParam(required=false) Long customerId,@RequestParam int year,@RequestParam(defaultValue="") String q,@RequestParam(defaultValue="") String outcome,@RequestParam(defaultValue="0") int page,Authentication a){require(a,false);validYear(year);if(customerId!=null)customer(customerId);if(page<0||page>100000||q.length()>100||!Set.of("","IN_PROGRESS","RESOLVED","PARTIAL","UNRESOLVED").contains(outcome))throw bad("Filtri non validi");String search="%"+q.toLowerCase(Locale.ROOT).replace("\\","\\\\").replace("%","\\%").replace("_","\\_")+"%";String w=FROM+" AND (?::bigint IS NULL OR r.customer_id=?) AND (extract(year FROM s.started_at AT TIME ZONE 'Europe/Rome')=? OR s.outcome='IN_PROGRESS') AND (?='' OR s.outcome=?) AND (lower(c.name) LIKE ? OR lower(s.requester_name) LIKE ? OR lower(u.full_name) LIKE ? OR lower(coalesce(r.notes,'')) LIKE ?)";Object[] args={customerId,customerId,year,outcome,outcome,search,search,search,search};var p=new ArrayList<>(Arrays.asList(args));p.add(20);p.add(page*20);return Map.of("items",db.queryForList(FIELDS+w+" ORDER BY (s.outcome='IN_PROGRESS') DESC,s.started_at DESC,s.record_id DESC LIMIT ? OFFSET ?",p.toArray()),"total",db.queryForObject("SELECT count(*)"+w,Long.class,args));}
 static void validYear(int year){if(year<2000||year>2100)throw bad("Anno non valido");}
 @GetMapping("/report") public Map<String,Object> report(@RequestParam(required=false) Long customerId,@RequestParam int year,Authentication a){require(a,false);validYear(year);if(customerId!=null)customer(customerId);
  var start=LocalDate.of(year,1,1).atStartOfDay(ZoneId.of("Europe/Rome")).toInstant();var end=LocalDate.of(year+1,1,1).atStartOfDay(ZoneId.of("Europe/Rome")).toInstant();
  String scope=" FROM penny_support_calls s JOIN penny_customer_records r ON r.id=s.record_id JOIN penny_customers c ON c.id=r.customer_id WHERE r.deleted_at IS NULL AND c.deleted_at IS NULL AND (?::bigint IS NULL OR r.customer_id=?)";
  var counts=db.queryForList("SELECT extract(month FROM s.started_at AT TIME ZONE 'Europe/Rome')::int AS month,count(*) FILTER(WHERE outcome='IN_PROGRESS') AS \"inProgress\",count(*) FILTER(WHERE outcome='RESOLVED') AS resolved,count(*) FILTER(WHERE outcome='PARTIAL') AS partial,count(*) FILTER(WHERE outcome='UNRESOLVED') AS unresolved"+scope+" AND s.started_at>=? AND s.started_at<? GROUP BY 1",customerId,customerId,java.sql.Timestamp.from(start),java.sql.Timestamp.from(end));var monthly=new ArrayList<Map<String,Object>>();for(int month=1;month<=12;month++){final int m=month;monthly.add(counts.stream().filter(row->((Number)row.get("month")).intValue()==m).findFirst().orElseGet(()->Map.of("month",m,"inProgress",0,"resolved",0,"partial",0,"unresolved",0)));}
  var technicians=db.queryForList("SELECT u.id,u.full_name AS name,sum(extract(epoch FROM (least(s.ended_at,?)-greatest(s.started_at,?))))::bigint AS seconds FROM penny_support_calls s JOIN penny_customer_records r ON r.id=s.record_id JOIN penny_customers c ON c.id=r.customer_id JOIN penny_users u ON u.id=s.technician_id WHERE r.deleted_at IS NULL AND c.deleted_at IS NULL AND (?::bigint IS NULL OR r.customer_id=?) AND s.ended_at IS NOT NULL AND s.started_at<? AND s.ended_at>? GROUP BY u.id,u.full_name ORDER BY seconds DESC,u.full_name",java.sql.Timestamp.from(end),java.sql.Timestamp.from(start),customerId,customerId,java.sql.Timestamp.from(end),java.sql.Timestamp.from(start));var requesters=db.queryForList("SELECT s.requester_name AS name,sum(extract(epoch FROM (least(s.ended_at,?)-greatest(s.started_at,?))))::bigint AS seconds"+scope+" AND s.ended_at IS NOT NULL AND s.started_at<? AND s.ended_at>? GROUP BY s.contact_id,s.requester_name ORDER BY seconds DESC,s.requester_name",java.sql.Timestamp.from(end),java.sql.Timestamp.from(start),customerId,customerId,java.sql.Timestamp.from(end),java.sql.Timestamp.from(start));long seconds=technicians.stream().mapToLong(r->((Number)r.get("seconds")).longValue()).sum();var years=db.queryForList("SELECT generate_series(extract(year FROM now() AT TIME ZONE 'Europe/Rome')::int,coalesce((SELECT min(extract(year FROM s.started_at AT TIME ZONE 'Europe/Rome'))::int"+scope+"),extract(year FROM now() AT TIME ZONE 'Europe/Rome')::int),-1) AS year",customerId,customerId);return Map.of("year",year,"monthly",monthly,"technicians",technicians,"requesters",requesters,"seconds",seconds,"years",years,"inProgress",db.queryForObject("SELECT count(*)"+scope+" AND outcome='IN_PROGRESS'",Long.class,customerId,customerId));
 }
}
